        adj[v].append(u)
    # Vertex 1 must become a leaf; all other branches hanging off vertex 1
    # must be deleted completely (each costs its size in operations), except
    # one branch that we keep. Then vertex 1 is removed with one more operation.
    # Cost = (N-1 - kept) + 1 = N - kept, minimized by keeping the largest branch.
    best_branch = 0
    seen = [False] * (n + 1)
    seen[1] = True
